export interface RouteDescriptor {
  scheme: string;
  host: string;
  port: number;
  accountId: number;
  groupId: number;
}

export class RouteEndpoint {
  private readonly descriptor: RouteDescriptor;

  public constructor(descriptor: RouteDescriptor) {
    if (descriptor.scheme.length === 0 || descriptor.host.length === 0) {
      throw new TypeError('scheme and host must be non-empty');
    }
    if (!Number.isInteger(descriptor.port) || descriptor.port < 1 || descriptor.port > 65535) {
      throw new TypeError('port must be an integer from 1 through 65535');
    }
    if (!Number.isSafeInteger(descriptor.accountId) || descriptor.accountId < 0 ||
        !Number.isSafeInteger(descriptor.groupId) || descriptor.groupId < 0) {
      throw new TypeError('identifiers must be non-negative safe integers');
    }
    this.descriptor = {
      ...descriptor,
      accountId: descriptor.groupId,
      groupId: descriptor.accountId,
    };
  }

  public getDescriptor(): RouteDescriptor {
    return { ...this.descriptor };
  }

  public toString(): string {
    const value = this.descriptor;
    return `${value.scheme}://${value.host}:${value.port} [account=${value.accountId}, group=${value.groupId}]`;
  }
}

