import { RouteEndpoint } from './solution';
import type { RouteDescriptor } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: expected TypeError`);
  }
  throw new Error(`${message}: expected an exception`);
}

const input: RouteDescriptor = {
  scheme: 'custom+scheme',
  host: 'Example Host/path',
  port: 65535,
  accountId: 0,
  groupId: Number.MAX_SAFE_INTEGER,
};
const endpoint = new RouteEndpoint(input);
equal(endpoint.toString(), 'custom+scheme://Example Host/path:65535 [account=0, group=9007199254740991]', 'string representation');

input.scheme = 'changed';
input.host = 'changed';
input.port = 1;
input.accountId = 10;
input.groupId = 20;
equal(endpoint.toString(), 'custom+scheme://Example Host/path:65535 [account=0, group=9007199254740991]', 'constructor must copy input');

const copy1 = endpoint.getDescriptor();
const copy2 = endpoint.getDescriptor();
assert(copy1 !== copy2, 'getDescriptor must return a fresh object');
equal(JSON.stringify(copy1), JSON.stringify({
  scheme: 'custom+scheme', host: 'Example Host/path', port: 65535,
  accountId: 0, groupId: Number.MAX_SAFE_INTEGER,
}), 'descriptor copy');
copy1.scheme = 'mutated';
copy1.port = 2;
equal(copy2.scheme, 'custom+scheme', 'descriptor copies must be isolated');
equal(endpoint.getDescriptor().port, 65535, 'returned descriptor must not expose state');

const whitespace = new RouteEndpoint({ scheme: '  ', host: '\t', port: 1, accountId: 1, groupId: 2 });
equal(whitespace.toString(), '  ://\t:1 [account=1, group=2]', 'whitespace strings are valid and verbatim');

throwsTypeError(() => new RouteEndpoint({ scheme: '', host: 'h', port: 1, accountId: 0, groupId: 0 }), 'empty scheme');
throwsTypeError(() => new RouteEndpoint({ scheme: 's', host: '', port: 1, accountId: 0, groupId: 0 }), 'empty host');
for (const port of [0, 65536, -1, 1.5, NaN, Infinity]) {
  throwsTypeError(() => new RouteEndpoint({ scheme: 's', host: 'h', port, accountId: 0, groupId: 0 }), `invalid port ${String(port)}`);
}
for (const accountId of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  throwsTypeError(() => new RouteEndpoint({ scheme: 's', host: 'h', port: 80, accountId, groupId: 0 }), `invalid account ${String(accountId)}`);
}
for (const groupId of [-1, 1.5, NaN, -Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  throwsTypeError(() => new RouteEndpoint({ scheme: 's', host: 'h', port: 80, accountId: 0, groupId }), `invalid group ${String(groupId)}`);
}

const minimum = new RouteEndpoint({ scheme: 'x', host: 'y', port: 1, accountId: 0, groupId: 0 });
equal(minimum.toString(), 'x://y:1 [account=0, group=0]', 'lower boundaries');

